// Generated lossless UTraffic network. Decode once per Edge worker.
const payload = "";
const compressed = Uint8Array.from(atob(payload), c => c.charCodeAt(0));
const stream = new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));
export const roadNetwork = JSON.parse(await new Response(stream).text());
export const roadNetworkSha256 = "95c44d74a54529d1157b39179cea465356758aadd1ae7852577201da19f38afc";
